package com.ultras.bans.gui;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.PunishmentType; import org.bukkit.event.*; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.entity.Player; import org.bukkit.inventory.ItemStack;
public final class GUIListener implements Listener {private final ULTRASBansPlugin p;private final GUIService g;public GUIListener(ULTRASBansPlugin p){this.p=p;this.g=p.gui();}public GUIService service(){return g;}@EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player x))return;if(!(e.getView().getTopInventory().getHolder() instanceof GUIService.Holder h))return;e.setCancelled(true);if(e.getClickedInventory()!=e.getView().getTopInventory())return;int s=e.getRawSlot();switch(h.type){case "players"->{if(s<45&&e.getCurrentItem()!=null&&e.getCurrentItem().getType()==org.bukkit.Material.PLAYER_HEAD){var meta=e.getCurrentItem().getItemMeta();if(meta instanceof org.bukkit.inventory.meta.SkullMeta sm&&sm.getOwningPlayer()!=null){g.openPunishment(x,sm.getOwningPlayer().getUniqueId());}}else if(s==48&&h.page>0)g.openPlayers(x,h.page-1);else if(s==50)g.openPlayers(x,h.page+1);else if(s==49)x.closeInventory();}case "punishment"->handlePunishment(x,h.uuid,s);case "duration"->{if(s==20){g.adjust(x,-1);g.refreshDuration(x);}else if(s==24){execute(x,h.uuid,g.pending(x),g.duration(x));}else if(s==49){g.openPunishment(x,h.uuid);}else if(s==22){g.adjust(x,1);g.refreshDuration(x);}}case "history"->{if(s==49)g.openPunishment(x,h.uuid);}}}
 private void handlePunishment(Player x,java.util.UUID u,int s){if(s==49){g.openPlayers(x,0);return;}if(s==20){g.pending(x,"BAN");g.openDuration(x,"BAN");}else if(s==21){g.openDuration(x,"BAN");}else if(s==22){g.pending(x,"IP_BAN");execute(x,u,"IP_BAN",0);}else if(s==23){g.openDuration(x,"IP_BAN");}else if(s==24){execute(x,u,"MUTE",0);}else if(s==29){g.openDuration(x,"MUTE");}else if(s==30){execute(x,u,"WARN",0);}else if(s==31){execute(x,u,"KICK",0);}else if(s==32){execute(x,u,"FREEZE",0);}else if(s==33){execute(x,u,"JAIL",0);}else if(s==38){execute(x,u,"UNBAN",0);}else if(s==39){execute(x,u,"UNMUTE",0);}else if(s==40){g.openHistory(x,u);}}
 private void execute(Player actor,java.util.UUID u,String action,long duration){var pTarget=p.getServer().getPlayer(u);String name=pTarget!=null?pTarget.getName():java.util.Optional.ofNullable(p.getServer().getOfflinePlayer(u).getName()).orElse("Unknown");PunishmentType t;try{t=PunishmentType.valueOf(action);}catch(Exception e){if(action.equals("UNBAN"))t=PunishmentType.BAN;else if(action.equals("UNMUTE"))t=PunishmentType.MUTE;else return;}if(action.startsWith("UN")){p.punishments().remove(u,t,actor).thenAccept(ok->actor.sendMessage(com.ultras.bans.utility.Text.c(ok?"<green>✓</green> ᴜʟᴛʀᴀs | Punishment removed.":"<yellow>⚠</yellow> ᴜʟᴛʀᴀs | No active punishment.")));return;}String ip=pTarget!=null&&pTarget.getAddress()!=null?pTarget.getAddress().getAddress().getHostAddress():"";p.punishments().apply(u,name,ip,t,duration,p.configs().get("punishment.yml").getString("default-reason"),actor,"PLAYER").thenAccept(ok->actor.sendMessage(com.ultras.bans.utility.Text.c(ok?"<green>✓</green> ᴜʟᴛʀᴀs | Punishment applied.":"<yellow>⚠</yellow> ᴜʟᴛʀᴀs | Player already has this punishment.")));}
}
